# owner: platform
"""Weekly timesheet lines built from a list of shifts."""

from hourglass.schedule import worker_minutes
from hourglass.errors import ProjectError
from collections import Counter

def _check(shifts):
    if not shifts:
        raise ProjectError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")

def _busiest(minutes):
    return sorted(
        minutes, key=lambda name: (-minutes[name], name)
    )

def _line(name, count, mins):
    return f"{name}, {count}, {mins / 60:.1f}"

# ---
def timesheet_lines(shifts):
    """Lines of 'name, shifts, hours', busiest first."""
    _check(shifts)
    minutes = worker_minutes(shifts)
    counts = Counter(item.worker for item in shifts)
    return [
        _line(name, counts[name], minutes[name])
        for name in _busiest(minutes)
    ]

